import type { ReactNode } from "react"
import { TrayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * Props for the {@link EmptyContent} composite.
 */
export interface EmptyContentProps {
    /** Primary "nothing here" line. */
    title: ReactNode
    /** Optional supporting line below the title. */
    description?: ReactNode
    /**
     * Override the default tray icon. Takes an already-built node (not a
     * component reference) ΓÇö every call site hands this a pre-sized glyph
     * (`<Icon className="size-8 ΓÇª" />`), so the shape stays a node here too.
     */
    icon?: ReactNode
    /** Optional retry/refresh handler ΓÇö renders a button when paired with a label. */
    onRetry?: () => void
    /** Translated label for the retry button (required to render it). */
    retryLabel?: ReactNode
}

/**
 * Standalone empty state ΓÇö a tray icon, a title + optional description, and
 * an optional "try again" button, centered. The standard `emptyContent` for
 * {@link import("../AsyncContent").AsyncContent}. Pure/props-only, one file (an
 * atom/composite never fetches or resolves i18n) ΓÇö text arrives already
 * translated from the caller.
 */
export const EmptyContent = ({
    title,
    description,
    icon,
    onRetry,
    retryLabel,
}: EmptyContentProps) => {
    const titleLines = [
        () => <Typography size="sm" weight="medium" align="center" text={title} />,
        ...(description
            ? [() => <Typography size="xs" color="muted" align="center" text={description} />]
            : []),
    ]

    return (
        <StackV identity={{ tier: "block", component: "EmptyContent" }}
            gap={4}
            align="center"
            justify="center"
            padding={6}
            items={[
                () => (
                    <>
                        {icon ?? (
                            <TrayIcon aria-hidden focusable="false" weight="duotone" className="size-8 text-foreground" />
                        )}
                    </>
                ),
                () => <StackV gap={2} principle="title-subtitle"
                    explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                    items={titleLines} />,
                ...(onRetry && retryLabel
                    ? [() => <Button variant="secondary" size="sm" onPress={onRetry} label={retryLabel} />]
                    : []),
            ]}
        />
    )
}

/** Tier metadata for `EmptyContent`, used by the component registry/Storybook lookup. */
export const meta = { tier: "composite", name: "EmptyContent" } as const

import { WarningOctagonIcon, type Icon as PhosphorIcon } from "@phosphor-icons/react"

import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"

/**
 * Props for the {@link ErrorContent} composite.
 */
export interface ErrorContentProps {
    /** Primary error line, already translated. */
    title: string
    /** Optional supporting line below the title (cause / what to do), already translated. */
    description?: string
    /** Override the default warning-octagon glyph ΓÇö a COMPONENT reference (Phosphor), never JSX. */
    icon?: PhosphorIcon
    /** Retry handler ΓÇö renders a button when paired with {@link ErrorContentProps.retryLabel}. */
    onRetry?: () => void
    /** Translated label for the retry button (required to render it). */
    retryLabel?: string
}

/**
 * Standalone error state ΓÇö a warning glyph, a title + optional description, and a
 * "try again" button, centered. Used directly by several screens as the retry
 * state for a failed fetch, and as the `errorContent` of the legacy
 * {@link import("@/components/blocks/async/AsyncContent").AsyncContent} switch.
 *
 * This is a COMPOSITE mislabeled by its folder (BLOCK-7): it takes no domain
 * entity, only already-resolved strings and a handler, so it never fetches and
 * never resolves i18n itself ΓÇö the caller always hands it translated text.
 *
 * @see Story: .storybook/stories/blocks/async/ErrorContent/ErrorContent.stories
 * @param props - {@link ErrorContentProps}
 */
export const ErrorContent = ({
    title,
    description,
    icon: Icon = WarningOctagonIcon,
    onRetry,
    retryLabel,
}: ErrorContentProps) => (
    <div data-tier="composite" data-component="ErrorContent">
        <StackV
            gap={4}
            align="center"
            padding={6}
            items={[
                () => <Icon aria-hidden focusable="false" weight="duotone" className="size-8 text-foreground" />,
                () => (
                    <StackV
                        gap={2}
                        principle="title-subtitle"
                        explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                        items={[
                            () => <Typography size="sm" weight="medium" align="center" text={title} />,
                            ...(description
                                ? [() => <Typography size="xs" color="muted" align="center" text={description} />]
                                : []),
                        ]}
                    />
                ),
                ...(onRetry && retryLabel
                    ? [() => <Button variant="secondary" size="sm" onPress={onRetry} label={retryLabel} />]
                    : []),
            ]}
        />
    </div>
)

/** Tier metadata for `ErrorContent`, used by the component registry/Storybook lookup. */
export const meta = { tier: "composite", name: "ErrorContent" } as const

"use client"

/** @noSkeleton renders an invisible scroll marker, not a value ΓÇö there is nothing behind it to wait for. */

import React from "react"

/** Props for {@link InfiniteScrollSentinel}. */
export interface InfiniteScrollSentinelProps {
    /** Fired once each time the sentinel scrolls into view (and `disabled` is false). */
    onReach: () => void
    /** When true the observer is detached (e.g. no more pages / a load in flight). */
    disabled?: boolean
    /** Scroll root to observe within (defaults to the viewport). */
    root?: Element | null
}

/**
 * Invisible end-of-list marker for infinite scroll: an `IntersectionObserver`
 * fires {@link InfiniteScrollSentinelProps.onReach} when it becomes visible, so
 * the list grows on scroll instead of via a "load more" button.
 *
 * Only for a list inside its OWN scroll container (modal / panel / rail) with
 * nothing below it. A list in the page's main column (footer underneath) must
 * use a "load more" button instead ΓÇö auto-loading steals the scroll and the
 * footer becomes unreachable. A finite list the user browses to pick from wants
 * a pager instead (compose `AsyncContent` with a pagination control).
 *
 * Pair with `useSWRInfinite` ΓÇö `onReach={() => setSize((s) => s + 1)}`,
 * `disabled={!hasMore || isLoadingMore}` where
 * `isLoadingMore = isValidating && (pages?.length ?? 0) < size`. While a page is
 * in flight, render skeletons mirroring 1-2 real items right here at the
 * sentinel, never a bare "loading" line.
 *
 * @see Story: .storybook/stories/blocks/async/InfiniteScrollSentinel/InfiniteScrollSentinel.stories
 * @param props - {@link InfiniteScrollSentinelProps}
 */
export const InfiniteScrollSentinel = ({
    onReach,
    disabled = false,
    root = null,
}: InfiniteScrollSentinelProps) => {
    const ref = React.useRef<HTMLDivElement>(null)
    // keep the latest callback without re-subscribing the observer each render
    const onReachRef = React.useRef(onReach)
    onReachRef.current = onReach

    React.useEffect(() => {
        const node = ref.current
        if (!node || disabled) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries.some((entry) => entry.isIntersecting)) {
                    onReachRef.current()
                }
            },
            { root, rootMargin: "120px" },
        )
        observer.observe(node)
        return () => observer.disconnect()
    }, [disabled, root])

    return (
        <div
            ref={ref}
            aria-hidden
            data-tier="atom"
            data-component="InfiniteScrollSentinel"
            className="h-px w-full"
        />
    )
}

/** Tier metadata for `InfiniteScrollSentinel`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "InfiniteScrollSentinel" } as const

"use client"

import React, {
    useMemo,
    useState,
    type ComponentType,
} from "react"
import {
    ArrowRightIcon,
    BookOpenIcon,
    CheckCircleIcon,
    UsersIcon,
} from "@phosphor-icons/react"
import {
    Button,
    Card,
    Chip,
    Typography,
    cn,
} from "@heroui/react"
import { PriceTagInline } from "@/components/blocks/commerce/PriceTag"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { CourseEntity } from "@/modules/types/entities/course"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link _CourseCard} ΓÇö presentational; all data + labels already resolved. */
export interface CourseCardProps {
    /** The course summarised by this card (list-item data). */
    course: CourseEntity
    /**
     * Loyalty-discounted VND price (what THIS viewer is actually charged, from
     * `coursePricePreview`). When set it takes over the price block so the catalog
     * shows the same personalised price as the rest of the app; omit for the phase
     * price (guests / not-yet-loaded).
     */
    loyaltyPriceVnd?: number | null
    /** List/original VND price struck through under the loyalty price. */
    loyaltyOriginalVnd?: number | null
    /**
     * Whether the loyalty preview is still resolving (authenticated viewer only ΓÇö
     * guests never set this). Skeletons the price line instead of showing the
     * phase price and then swapping to the loyalty price a beat later.
     */
    loyaltyPending?: boolean
    /**
     * Layout: a roomy `"grid"` card (default ΓÇö cover + outcomes + price) or a
     * compact `"line"` row (thumbnail + title + price + CTA on one line). Lets the
     * catalog offer a grid Γçå list view toggle without a second card component.
     */
    layout?: "grid" | "line"
    /**
     * Optional trailing action node (e.g. an "Add to cart" button) rendered beside
     * the View CTA. The block only places it; the caller (a feature) owns its logic
     * so the card stays presentational.
     */
    action?: ComponentType
    /** Already-localized primary CTA label ("Continue learning" once enrolled, else "View course"). */
    viewLabel: string
    /** Already-localized secondary "View course" label, shown once enrolled (beside the primary CTA). */
    viewCourseLabel: string
    /** Already-localized "N learners" chip label; omitted when the course has no enrollments. */
    learnersLabel?: string
    /** Already-localized/formatted USD price hint line; omitted when there's no USD price. */
    priceUsdHintLabel?: string
    /** Fired by the primary CTA ΓÇö continue learning if enrolled, else go to the marketing page. */
    onView: () => void
    /** Fired by the secondary "View course" button shown once enrolled. */
    onViewDetail: () => void
}

/**
 * Featured course card (catalog block): cover (with branded fallback), title,
 * outcome, social proof + top value propositions, and a price block (active-phase
 * price, original strikethrough + % off when discounted, optional USD hint) with a
 * view CTA. Owns its whole look so features just feed the `course`.
 *
 * @param props - {@link CourseCardProps}
 */
export const _CourseCard = ({
    course,
    loyaltyPriceVnd,
    loyaltyOriginalVnd,
    loyaltyPending = false,
    layout = "grid",
    action: Action,
    viewLabel,
    viewCourseLabel,
    learnersLabel,
    priceUsdHintLabel,
    onView,
    onViewDetail,
}: CourseCardProps) => {
    const [coverFailed, setCoverFailed] = useState(false)

    // display transform for ENTITY-derived (fallback) VND prices so the catalog matches
    // the rest of the app: ├╖ testDivisor in non-prod. The loyalty price (from
    // `coursePricePreview`) is ALREADY transformed ΓåÆ not re-applied.
    const divisor = publicEnv().pricing.testDivisor
    const toVnd = (amount: number): number =>
        divisor === 1 ? amount : Math.max(1, Math.round(amount / divisor))

    /** Active-phase price (falls back to the list/regular price when no phase row). */
    const currentPrice = useMemo(
        () => course.pricingPhases?.find(
            (pricingPhase) => pricingPhase.phase === course.currentPhase,
        )?.price ?? course.originalPrice ?? null,
        [course.pricingPhases, course.currentPhase, course.originalPrice],
    )

    /** Top three value propositions shown as a quick "what you'll learn" list. */
    const topValueProps = useMemo(
        () => (course.valuePropositions ?? []).slice(0, 3),
        [course.valuePropositions],
    )

    // enrolled ΓåÆ the marketing/detail page is the wrong destination for the PRIMARY
    // action (the viewer already owns this course); the connected half already routed
    // `onView` into the learning experience. The marketing page is still a legitimate
    // secondary destination once enrolled (re-check the syllabus, share the link).
    const isEnrolled = course.isEnrolled === true
    // not enrolled ΓåÆ the feature-owned `action` slot (cart-add, hides itself for
    // free/enrolled courses per its own logic). Enrolled ΓåÆ that slot would render
    // null anyway, so replace it with a secondary "View course" button (view the
    // marketing page) ΓÇö teacher: "a card for an already-purchased course should have
    // 2 parts: continue learning (primary) and view course (secondary)", don't just
    // drop the second button once enrolled.
    const secondaryAction = isEnrolled ? (
        // no trailing arrow ΓÇö arrow marks the ONE primary CTA per surface
        // (button.md ┬º2: "a button WITHOUT an icon = sub-CTA"); keeping it here as
        // well as on "Continue learning" made both buttons read as equally weighted.
        <Button
            variant="secondary"
            onPress={onViewDetail}
            className="flex-1"
        >
            {viewCourseLabel}
        </Button>
    ) : Action ? <Action /> : null

    const showCover = Boolean(course.coverImageUrl) && !coverFailed

    // price block: prefer the viewer's loyalty price (uniform with the rest of the app)
    // when supplied, else fall back to the active-phase price.
    const useLoyalty = loyaltyPriceVnd != null
    const displayPrice = useLoyalty
        ? loyaltyPriceVnd
        : (currentPrice != null ? toVnd(currentPrice) : null)
    const displayOriginal = useLoyalty
        ? loyaltyOriginalVnd ?? null
        : (course.originalPrice != null ? toVnd(course.originalPrice) : null)

    // compact LINE row (catalog list view): thumbnail + title/description, with the
    // price + view CTA on the right ΓÇö one course per row for fast scanning.
    if (layout === "line") {
        return (
            <Card className={cn("overflow-hidden rounded-3xl")}>
                {/* plain div, NOT Card.Content ΓÇö `.card__content` bakes flex-col
                    (unlayered), so `items-center` on it centers vertically instead of
                    laying the row out horizontally. The card root already insets its
                    children (baked `p-4`), so this row carries no padding of its own. */}
                <div className="flex items-center gap-3">
                    {/* thumbnail 16:9 (branded fallback); hidden on the narrowest screens.
                        rounded-2xl = the "inner" step under the card's rounded-3xl. */}
                    <div className="relative hidden aspect-video w-36 shrink-0 overflow-hidden rounded-2xl bg-surface @app-sm:block">
                        {showCover ? (
                            <img
                                src={course.coverImageUrl ?? undefined}
                                alt={course.title}
                                className="size-full object-cover"
                                onError={() => setCoverFailed(true)}
                            />
                        ) : (
                            <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5">
                                <BookOpenIcon aria-hidden className="size-8 text-accent-soft-foreground" />
                            </div>
                        )}
                    </div>
                    {/* title + one-line description */}
                    <div className="flex min-w-0 flex-1 flex-col gap-1">
                        <div className="flex items-center gap-2">
                            <Typography type="body" weight="bold" truncate>
                                {course.title}
                            </Typography>
                            {learnersLabel != null ? (
                                <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                    <UsersIcon aria-hidden className="size-4" />
                                    <Chip.Label>
                                        {learnersLabel}
                                    </Chip.Label>
                                </Chip>
                            ) : null}
                        </div>
                        <Typography type="body-sm" color="muted" className="line-clamp-1">
                            {course.description}
                        </Typography>
                    </div>
                    {/* price row, then a button row below ΓÇö view CTA is now a real primary
                        Button (not a subtle Link), per starci-fe-block-variants round-2
                        direction "C". `size="md"` per button.md ┬º3's compact-context
                        exception (a repeated grid card is a tight context ΓÇö `lg` would
                        blow up row height across many cards). */}
                    <div className="flex shrink-0 flex-col items-end gap-2">
                        {loyaltyPending ? (
                            <Skeleton.Typography type="body-sm" width="1/2" />
                        ) : displayPrice != null ? (
                            <PriceTagInline
                                discounted={displayPrice}
                                original={displayOriginal}
                               
                            />
                        ) : null}
                        <div className="flex w-full items-center gap-2">
                            <Button
                                variant="primary"
                                onPress={onView}
                                className="flex-1"
                            >
                                {viewLabel}
                                <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                            </Button>
                            {secondaryAction}
                        </div>
                    </div>
                </div>
            </Card>
        )
    }

    return (
        <Card className={cn("flex flex-col overflow-hidden rounded-3xl")}>
            <Card.Content className="flex flex-col gap-3">
                {/* cover 16:9 ΓÇö rounded-2xl = the "inner" step under the card's
                    rounded-3xl (was full-bleed/unrounded, mismatched the line thumb);
                    the card root already insets its children (baked `p-4`); branded
                    gradient fallback when missing/broken */}
                <div className="relative aspect-video w-full overflow-hidden rounded-2xl bg-surface">
                    {showCover ? (
                        <img
                            src={course.coverImageUrl ?? undefined}
                            alt={course.title}
                            className="size-full object-cover"
                            onError={() => setCoverFailed(true)}
                        />
                    ) : (
                        <div className="flex size-full items-center justify-center bg-gradient-to-br from-accent/25 to-accent/5 p-4">
                            <BookOpenIcon aria-hidden className="size-10 text-accent-soft-foreground" />
                            <Typography type="body-sm" weight="semibold" align="center" className="ml-2">
                                {course.title}
                            </Typography>
                        </div>
                    )}
                </div>

                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Typography type="h6" weight="bold" truncate>
                            {course.title}
                        </Typography>
                        {learnersLabel != null ? (
                            <Chip variant="secondary" color="accent" size="sm" className="shrink-0">
                                <UsersIcon aria-hidden className="size-4" />
                                <Chip.Label>
                                    {learnersLabel}
                                </Chip.Label>
                            </Chip>
                        ) : null}
                    </div>
                    <Typography type="body-sm" color="muted" className="line-clamp-2">
                        {course.description}
                    </Typography>
                    {topValueProps.length > 0 ? (
                        <ul className="mt-1 flex flex-col gap-2">
                            {topValueProps.map((valueProp, index) => (
                                <li key={index} className="flex items-start gap-2">
                                    <CheckCircleIcon aria-hidden className="size-4 shrink-0 text-success-soft-foreground" />
                                    <Typography type="body-xs" color="muted">
                                        {valueProp.text}
                                    </Typography>
                                </li>
                            ))}
                        </ul>
                    ) : null}
                </div>
            </Card.Content>
            <Card.Footer className="mt-auto flex flex-col gap-2">
                {/* price row (informational) */}
                <div className="flex items-center gap-2">
                    {loyaltyPending ? (
                        <Skeleton.Typography type="body-sm" width="1/2" />
                    ) : displayPrice != null ? (
                        <PriceTagInline
                            discounted={displayPrice}
                            original={displayOriginal}
                           
                        />
                    ) : (
                        <span />
                    )}
                </div>
                {priceUsdHintLabel != null ? (
                    <Typography type="body-xs" color="muted">
                        {priceUsdHintLabel}
                    </Typography>
                ) : null}
                {/* action row ΓÇö view CTA is a real primary Button (not a subtle Link), per
                    starci-fe-block-variants round-2 direction "C": the previous accent Link
                    read as a secondary "see more" action rather than the card's actual primary
                    action. `size="md"` per button.md ┬º3's compact-context exception (a
                    repeated grid card is tight ΓÇö `lg` would blow up card height across many
                    cards). Cart-add stays `action` (secondary, pairs with this primary). */}
                <div className="flex w-full items-center gap-2">
                    <Button
                        variant="primary"
                        onPress={onView}
                        className="flex-1"
                    >
                        {viewLabel}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-4" />
                    </Button>
                    {secondaryAction}
                </div>
            </Card.Footer>
        </Card>
    )
}

"use client"

import React, { type ComponentType } from "react"
import {
    cn,
} from "@heroui/react"
import {
    CaretRightIcon as ChevronRightIcon,
} from "@phosphor-icons/react"
import {
    PressableCard,
} from "../PressableCard"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Props for {@link SummaryCard}. Every field is an already-resolved shape
 * (icon, value, label, hint) ΓÇö this card takes no domain entity, which is
 * why it lives at the composite tier despite sitting in `blocks/cards`
 * (BLOCK-7): the folder names a tier the component never earned.
 */
export interface SummaryCardProps {
    /** Leading icon for the metric ΓÇö a buildable slot, not a built element. */
    icon: ComponentType
    /** Headline value (e.g. a count). */
    value: string
    /** Short label under the value. */
    label: string
    /** Optional one-line hint under the label. */
    hint?: string
    /** Called when the card is activated (e.g. jump to a tab). */
    onPress?: () => void
}

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "SummaryCard" } as const

/**
 * A compact pressable metric card (icon + big value + label, with a trailing
 * chevron) used in the profile overview to surface a deeper tab. Built on
 * {@link PressableCard} for the spring/hover feel; layers its own outlined
 * "default" card look on top of that surface. Presentational ΓÇö the caller
 * wires `onPress`.
 *
 * `PressableCard` has not itself been ported to the closed `classNames`
 * vocabulary, so its `className` string prop is composed here with `cn`
 * (COMPOSITE-5 ΓÇö appearance is this tier's job); `SummaryCard` renders no
 * `<div>` of its own beyond what `PressableCard`'s button/anchor already
 * emits, so it carries no separate `data-tier`/`data-component` badge ΓÇö
 * `PressableCard` offers no slot for one, and wrapping it in an extra `<div>`
 * just to hang the badge on would be the identity wrapper the composite tier
 * says not to add.
 *
 * @param props - {@link SummaryCardProps}
 */
export const SummaryCard = ({
    icon: Icon,
    value,
    label,
    hint,
    onPress,
}: SummaryCardProps) => {
    const rows = [
        () => (
            <StackH
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                justify="between"
                items={[
                    () => <span className="text-accent-soft-foreground"><Icon /></span>,
                    () => <ChevronRightIcon className="size-5 text-muted" />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={1}
                items={[
                    () => <Typography size="h4" weight="bold" text={value} />,
                    () => <Typography size="sm" weight="medium" text={label} />,
                    ...(hint ? [() => <Typography size="xs" color="muted" text={hint} />] : []),
                ]}
            />
        ),
    ]

    return (
        <PressableCard
            identity={{ tier: "block", component: "SummaryCard" }}
            onPress={onPress}
            className={cn(
                "card card--default h-full rounded-xl border border-divider/60 p-4 transition-colors",
                "hover:border-accent/40 hover:bg-accent/5",
            )}
        >
            <StackV gap={4} items={rows} />
        </PressableCard>
    )
}

import React from "react"
import { Typography, cn } from "@heroui/react"
import { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"

/**
 * The model-category ΓåÆ dot color scale ΓÇö the SINGLE source of truth for the tier
 * ramp. A Tailwind palette ramp, not the semantic tokens: a capability tier is not a
 * status. The two embedding axes sit off the low/medium/high ramp. Change it here once.
 */
export const AI_CATEGORY_COLOR: Record<AiModelCategory, string> = {
    [AiModelCategory.Low]: "bg-slate-400",
    [AiModelCategory.Medium]: "bg-cyan-500",
    [AiModelCategory.High]: "bg-amber-500",
    [AiModelCategory.EmbeddingBulk]: "bg-violet-500",
    [AiModelCategory.EmbeddingDoc]: "bg-emerald-500",
}

/** Props for {@link _AiCategoryChip} ΓÇö presentational; label already resolved. */
export interface AiCategoryChipProps {
    /** Cost/quality category that drives the dot color. */
    category: AiModelCategory
    /** Already-localized category name. */
    label: string
}

/**
 * GitHub-style badge for an AI model's cost/quality category ΓÇö the single source for
 * the model-category badge across the grade picker and the AI lab. A small
 * tier-coloured dot followed by the localized category name, mirroring
 * {@link import("../LanguageChip").LanguageChip}'s shape. No pill/box; the dot
 * carries the colour. Colour comes from the shared {@link AI_CATEGORY_COLOR} scale.
 *
 * @param props - {@link AiCategoryChipProps}
 * @see Story: .storybook/stories/blocks/chips/AiCategoryChip/AiCategoryChip.stories
 */
export const _AiCategoryChip = ({ category, label }: AiCategoryChipProps) => (
    <span className="inline-flex items-center gap-2">
        <span aria-hidden className={cn("size-3 shrink-0 rounded-full", AI_CATEGORY_COLOR[category])} />
        <Typography type="body-xs" color="muted">
            {label}
        </Typography>
    </span>
)

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"
import { TierLevelIcon } from "@/components/svg/TierLevelIcon"
import { TierCardBase } from "@/components/blocks/commerce/TierCardBase"

/**
 * Free-tier base credit allowance ΓÇö mirrors the backend free auto quota default
 * (`systemConfig.ai.auto`, base 50 / 5h ┬╖ 500 / week). Shown so the free card
 * states its credits like the paid tiers.
 */
const FREE_CREDITS_PER_5H = 50
const FREE_CREDITS_PER_WEEK = 500

/** Props for {@link FreeTierCard}. */
export interface FreeTierCardProps {
    /** True when the user is currently on the free tier (no paid subscription). */
    isCurrent: boolean
    /** First load ΓåÆ the shell rests; the twin that used to mirror this card is gone. */
    isSkeleton?: boolean
}

/**
 * Static free-tier card (not purchasable).
 *
 * Presentational: composes {@link TierCardBase}, showing the "current plan"
 * chip when active, otherwise a disabled CTA. No business logic.
 * @param props - whether the free tier is the user's current plan
 */
export const FreeTierCard = ({
    isCurrent,
    isSkeleton = false}: FreeTierCardProps) => {
    const t = useTranslations()
    return (
        <TierCardBase
            identity={{ tier: "block", component: "FreeTierCard" }}
            isSkeleton={isSkeleton}
            icon={() => (
                <TierLevelIcon
                    level={1}
                    className="size-6 shrink-0 text-accent-soft-foreground"
                />
            )}
            title={t("aiSubscription.free.title")}
            description={t("aiSubscription.free.desc")}
            price={() => (
                <>
                    <Typography size="h3" weight="bold" text={t("aiSubscription.free.price")} />
                    {/* spacer ΓÇö matches paid tiers' USD hint block so CTAs align */}
                    <div
                        className="h-[3lh]"
                        aria-hidden
                    />
                </>
            )}
            features={[
                t("aiSubscription.creditsPer5h", { credits: FREE_CREDITS_PER_5H }),
                t("aiSubscription.creditsPerWeek", { credits: FREE_CREDITS_PER_WEEK }),
            ]}
            isCurrent={isCurrent}
            cta={() => (
                <StackV
                    principle="center-measure"
                    explain="Stretches the disabled free-tier CTA across the card foot so it aligns with paid-tier buy buttons."
                    items={[
                        () => (
                            <Button
                                variant="secondary"
                                isDisabled
                                label={t("aiSubscription.free.cta")}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

import React from "react"
import { WarningCircleIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"

/**
 * `PhaseScarcityNote` ΓÇö the scarcity line for a pricing phase. Every number
 * comes from the backend's `coursePricePreview`; it never fabricates a
 * countdown or seat count, and a phase with no seat cap renders nothing.
 */

/**
 * Props for {@link _PhaseScarcityNote}. The two sentences are REQUIRED unless
 * `isSkeleton` (┬º12b) ΓÇö the price preview hasn't arrived yet, so there is no
 * honest phase/seat fact to state. They arrive already localized: the phase name
 * and the interpolated copy are the connected half's to resolve.
 */
export type PhaseScarcityNoteBaseProps =
    | { isSkeleton: true; seatsRemaining?: number | null; slotsLeftLabel?: string | null; priceRisingLabel?: string | null }
    | {
        isSkeleton?: false
        /** Seats left at this phase's price; `null` = unlimited ΓåÆ renders NOTHING. */
        seatsRemaining: number | null
        /** "N seats left at the X price", already localized. */
        slotsLeftLabel: string | null
        /** "price rises to Y after that", already localized; `null` = no rise to mention. */
        priceRisingLabel: string | null
    }

/**
 * Honest scarcity line for a paywall. Sits as a DIRECT SIBLING below `PriceTag`
 * (PriceTag handles discounting; scarcity is a different, orthogonal push axis).
 *
 * Only renders when the current phase has a **real seat cap**
 * (`seatsRemaining != null`) ΓÇö an unlimited phase has no honest "rises when"
 * milestone to state, so it stays silent. EVERY number comes from the
 * backend's `coursePricePreview` ΓÇö this file NEVER makes up a countdown or
 * seat count (fake scarcity is a banned dark pattern).
 *
 * @param props - {@link PhaseScarcityNoteBaseProps}
 */
const _PhaseScarcityNote = ({
    seatsRemaining,
    slotsLeftLabel,
    priceRisingLabel,
    isSkeleton = false,
}: PhaseScarcityNoteBaseProps) => {
    if (isSkeleton) {
        return <Typography size="sm" isSkeleton />
    }
    // no seat cap at this phase ΓåÆ no honest scarcity reason ΓåÆ stay silent
    if (seatsRemaining == null) {
        return null
    }

    return (
        // Color is set ON THE FRAME; text inside does NOT declare `color`, so it
        // inherits `currentColor` ΓÇö the exact `warning-soft-foreground` tone.
        //
        // This row is ONE TRACK of N elements that wrap ΓçÆ exactly the definition
        // of `Cluster`, and repeated lists go through `items` DATA (children are
        // forbidden).
        //
        // What's gained isn't "fewer classes" but that `gap` is now PINNED to
        // the scale BY TYPE: hand-written it's `gap-2` today, `gap-1.5`
        // tomorrow, nothing stops that.
        <div className="text-warning-soft-foreground">
            <Cluster
                gap={3}
                principle="separator-dot"
                explain="Places a middle-dot separator between short meta peers so the items read as one inline list."
                align="center"
                // The `┬╖` between the two clauses is drawn by the FRAME, not written as a text item.
                // A mark that separates a track's items belongs to the track, the same way a rule
                // does; written as content it also produced a `Separator` node in the structure tree
                // whose link went to the generic Typography story.
                separator
                items={[
                    () => (
                        // ┬º5a: icon matches the FONT-SIZE of the text beside it ΓÇö `sm`
                        // (14px) ΓçÆ `size-3.5`. ┬º5.0a: below `size-5` ΓçÆ force
                        // `weight="bold"` to compensate for the thin strokes.
                        <WarningCircleIcon
                            aria-hidden
                            focusable="false"
                            weight="bold"
                            className="size-3.5 shrink-0"
                        />
                    ),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            text={slotsLeftLabel}

                        />
                    ),
                    // The next two pieces go TOGETHER (no rise means nothing to separate
                    // it from) ΓÇö but they're still TWO SEPARATE cluster items, since the
                    // `┬╖` mark must be allowed to wrap onto the line with the piece after
                    // it when the row runs tight.
                    ...(priceRisingLabel != null
                        ? [
                            () => (
                                <Typography
                                    size="sm"
                                    text={priceRisingLabel}

                                />
                            ),
                        ]
                        : []),
                ]}
            />
        </div>
    )
}

export { _PhaseScarcityNote }

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Popover } from "@heroui/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Cluster } from "@/components/frames/Cluster"
import { StackV } from "@/components/frames/Stack"
import { type CallerIdentity } from "@/components/frames/_identity"
import { KeyValueList } from "@/components/composites/data/KeyValue"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * DESIGN ΓÇö a single course/product price: the amount to pay (bold), the struck
 * list price, a `ΓêÆX%` success chip, and a breakdown popover.
 *
 * ANATOMY IS PER-LEAF: each story below is its OWN leaf and wraps its render in
 * its OWN BlockAnatomy (Diagram + Tree) reflecting the parts THAT leaf composes ΓÇö
 * there is no separate consolidated "Anatomy" story. The composition shifts with
 * the shape: no-discount shows only the amount; on-sale adds the struck price,
 * chip, popover, and saving line; `showSavingLine={false}` drops that last line.
 */

/** Currency a price is shown in. */
export type PriceCurrency = "VND" | "USD"

/**
 * How loud the price is on its surface ΓÇö decides the amount's font size. INTERNAL,
 * and deliberately NOT named `role`: that word is a DOM/ARIA attribute, so a prop by
 * that name reads as an accessibility role to both a reader and to eslint-jsx-a11y
 * (which flagged `role="prominent"` as an invalid ARIA role three times).
 * not exposed as a prop (┬º14d.1): the caller picks a MEMBER (`PriceTagInline` /
 * `PriceTagProminent`), not a size.
 */
export type PriceEmphasis = "inline" | "prominent"

/** Breakdown rows for the breakdown popover (amounts in the SAME currency as the price). */
export interface PriceBreakdown {
    /** Active-phase price BEFORE loyalty (the middle step list -> phase -> charge). */
    phase: number
    /** Localised phase name (e.g. "Early-bird") shown on the phase row. */
    phaseLabel?: string
    /** Loyalty discount percent (0 = no loyalty row). */
    loyaltyPercent: number
    /** Localised loyalty note (e.g. "already owns 2 courses") appended to the loyalty row. */
    loyaltyNote?: string
}

/** Every word the breakdown popover says ΓÇö resolved by the connected {@link PriceTag}. */
export interface PriceTagLabels {
    /** Popover heading, and its accessible name. */
    breakdownTitle: string
    /** Row label for the pre-discount price. */
    listPrice: string
    /** Row label for the phase discount (already folded with the phase name when there is one). */
    phaseRow: string
    /** Row label for the loyalty discount (already folded with the loyalty note when there is one). */
    loyaltyRow: string
    /** Row label for the total the buyer actually pays. */
    youPay: string
}

/** Props for the {@link PriceTag} block. */
export interface PriceTagProps {
    /** Breakdown-popover copy, already localized. A story passes i18n keys. */
    labels: PriceTagLabels
    /** The price the user actually pays. */
    discounted: number
    /** The pre-discount (list/MSRP) price; struck through when greater than discounted. */
    original?: number | null
    /** Currency to format in. Defaults to "VND". */
    currency?: PriceCurrency
    /**
 * `true` -> the price is in its RESTING state: the amount, the struck-through
 * original price, the `ΓêÆX%` chip, and the saving line all turn to shimmer,
 * KEEPING the same line boxes so nothing jumps in layout (┬º8).
 *
 * The flag FLOWS DOWN into the atoms that render each part (`Typography`,
 * `Chip`), instead of building a second shimmer tree (┬º12c). The popover
 * is TURNED OFF while resting ΓÇö there is no data to open yet, and a pressable
 * control while loading is a false promise.
 */
    isSkeleton?: boolean
    /**
 * Optional phase-tier + loyalty rows for the breakdown {@link Popover}. Whenever
 * there IS a saving the `ΓêÆX%` chip is ALWAYS a button that opens the popover (at
 * minimum list price -> "you pay"); `breakdown` just adds the middle steps that
 * explain WHERE the drop came from. Click/tap (not hover) so it works on touch too.
 */
    breakdown?: PriceBreakdown
    /**
 * Show the concrete "save NΓé½" line under the price (the real VND saved, not just
 * the percent). Defaults to `true`; set `false` where space is tight (dense cards).
 */
    showSavingLine?: boolean
}

/**
 * Role -> amount font size.
 */
const AMOUNT_TYPE: Record<PriceEmphasis, "base" | "h4"> = {
    inline: "base",
    prominent: "h4",
}

/** Role -> struck-through original-price line size, placed next to {@link AMOUNT_TYPE} so the two scales don't drift apart. */
const ORIGINAL_TYPE: Record<PriceEmphasis, "xs" | "sm"> = {
    inline: "xs",
    prominent: "sm",
}

/** Format an amount in the given currency. */
export const formatPrice = (amount: number, currency: PriceCurrency): string =>
    currency === "USD"
        ? amount.toLocaleString("en-US", { style: "currency", currency: "USD" })
        : `${amount.toLocaleString("vi-VN")}Γé½`

/** Whole-percent saving between a "before" and an "after" amount (0 when none). */
const savingPercent = (before: number, after: number): number =>
    before > after ? Math.round((1 - after / before) * 100) : 0

/**
 * The single source of truth for rendering a course/product price: the discounted
 * amount (bold), the list price struck through (only when there IS a saving), and a
 * `ΓêÆX%` success chip whose percent is the REAL list -> charge gap (phase tier +
 * loyalty). Whenever there is a saving the chip is a clickable button opening a
 * {@link Popover} (at minimum list price -> you pay; `breakdown` adds the phase +
 * loyalty steps). Works in VND or USD.
 *
 * @param props - {@link PriceTagProps}
 */
export const PriceTagBase = ({
    discounted,
    original,
    currency = "VND",
    emphasis,
    isSkeleton = false,
    breakdown,
    showSavingLine = true,
    labels,
    identity,
}: PriceTagProps & { emphasis: PriceEmphasis; identity?: CallerIdentity }) => {
    const hasSaving = original != null && original > discounted
    const savePercent = hasSaving ? savingPercent(original, discounted) : 0

    // the ΓêÆX% saving chip ΓÇö composed from the `Chip` atom (tone success ->
    // soft-success chip, matching src's raw `<Chip variant="soft" color="success">`).
    // The pressable/focusable button role lives on the canonical `Popover.Trigger`
    // wrapper (react-aria: role=button, aria-expanded/controls, tabindex), so there is
    // exactly ONE interactive element. No caret; the whole chip is the affordance.
    const chip =
        savePercent > 0 ? (
            <Chip
                tone="success"
                text={`ΓêÆ${savePercent}%`}
            />
        ) : null

    // phase saving = list -> phase ; loyalty saving = phase -> charge
    const phaseSave = original != null ? savingPercent(original, breakdown?.phase ?? discounted) : 0
    // Popover content ΓÇö shown for EVERY saving (so the chip is always clickable), at
    // minimum list price -> you pay. The phase-tier & loyalty rows only appear when a
    // full `breakdown` is supplied.
    const breakdownContent = hasSaving ? (
        // Those four rows are all ONE shape: label left <-> value right, repeated =>
        // exactly `KeyValueList` (a repeated list => `items` is DATA). The "you
        // pay" row is the TOTAL row => `emphasis`, not a hand-drawn rule: the frame
        // already knows how to emphasise a total row, and that emphasis looks the same
        // across every price table in the system.
        //
        // WARNING∩╕Å The frame does NOT format for you: every money string coming in here
        // has already gone through `formatPrice`.
        // WARNING∩╕Å This column is NOT badged: the panel groups nodes BY NAME (`firstEl` keeps
        // only the first element of each name), so two `StackV`s with the same name
        // would MERGE into one node and the tree would read wrong. The node that
        // matters inside the popover is `KeyValueList` ΓÇö that one is badged; the
        // wrapping column is just `p-3` padding.
        // Two vertical rows inside a design (the eyebrow and the breakdown list) =
        // `grouped`, not `tight`. `tight` (1) is reserved for what sits INSIDE a
        // composite, e.g. the icon+label pair of `InlineIconLabel`.
        <StackV gap={4} principle="cell-pad"
            explain="Tight cell inset ΓÇö not card-padding, because this sits inside a dense table or list cell rather than a card body."
            padding={4} isSkeleton={isSkeleton} body={() => (
                <StackV gap={4} principle="label-field"
                    explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
                    isSkeleton={isSkeleton} items={[
                        ({ isSkeleton }: SkeletonProps) => <Typography size="xs" color="muted" text={labels.breakdownTitle} isSkeleton={isSkeleton} />,
                        // No `gap` passed: `KeyValueList` already owns its row rhythm (its own default
                        // is the ┬º10b `grouped` step). Passing one from here overrides the composite's
                        // spacing from OUTSIDE, which ┬º10 forbids ΓÇö a composite owns its internal
                        // spacing and must not receive it.
                        ({ isSkeleton }: SkeletonProps) => (
                            <KeyValueList
                                isSkeleton={isSkeleton}
                                items={[
                                    {
                                        key: "list",
                                        label: labels.listPrice,
                                        value: formatPrice(original ?? discounted, currency),
                                    },
                                    ...(breakdown && original != null && original > breakdown.phase
                                        ? [{
                                            key: "phase",
                                            label: labels.phaseRow,
                                            // NOTE: `KeyValueListItem.value` is now a plain `string` ΓÇö this row
                                            // loses the `color="success-soft"` (green) tint it used to carry via
                                            // its own `Typography`. `KeyValueRow` only renders `value` through the
                                            // emphasis/plain split, no per-row tone prop. Preserving the green
                                            // accent needs either accepting the loss (done here) or a future
                                            // `tone`/`accent` field on `KeyValueListItem` ΓÇö left for whoever owns
                                            // PriceTag/KeyValue next, not decided in this pass.
                                            value: `ΓêÆ${formatPrice(original - breakdown.phase, currency)} (ΓêÆ${phaseSave}%)`,
                                        }]
                                        : []),
                                    ...(breakdown && breakdown.loyaltyPercent > 0 && breakdown.phase > discounted
                                        ? [{
                                            key: "loyalty",
                                            label: labels.loyaltyRow,
                                            // See the "phase" row's note above ΓÇö same loss of the green tint,
                                            // same reason.
                                            value: `ΓêÆ${formatPrice(breakdown.phase - discounted, currency)} (ΓêÆ${breakdown.loyaltyPercent}%)`,
                                        }]
                                        : []),
                                    {
                                        key: "total",
                                        label: labels.youPay,
                                        value: formatPrice(discounted, currency),
                                        // the TOTAL row: the frame handles the emphasis, replacing a hand-typed `border-t ΓÇª pt-1`
                                        emphasis: true,
                                    },
                                ]}
                            />
                        ),
                    ]} />
            )} />
    ) : null

    // The price row aligns on BASELINE (big number, struck number, chip share the
    // same text baseline) and wraps on its own when tight => exactly `Cluster`.
    // The three elements are THREE separate items, not merged into one
    // fragment ΓÇö merging them leaves the frame's `gap` with nowhere to apply.
    const priceRow = (
        <Cluster
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            align="baseline"

            items={[
                // The amount goes through the ATOM `Typography` (┬º9c), NOT raw
                // HeroUI ΓÇö thanks to that, `isSkeleton` flows straight into it instead
                // of branching off to build a separate shimmer bar.
                () => (
                    <Typography
                        size={AMOUNT_TYPE[emphasis]}
                        weight="bold"
                        isSkeleton={isSkeleton}
                        text={formatPrice(discounted, currency)}
                    />
                ),
                ...(hasSaving
                    ? [() => (
                        <Typography
                            size={ORIGINAL_TYPE[emphasis]}
                            color="muted"
                            isSkeleton={isSkeleton}
                            isStruck
                            text={formatPrice(original, currency)}
                        />
                    )]
                    : []),
                // While resting: the chip still holds its place but is NOT wrapped in a
                // Popover ΓÇö there's no data yet to open, and a pressable control while
                // loading is a false promise.
                ...(isSkeleton
                    ? [() => <Chip isSkeleton />]
                    : savePercent > 0
                        ? [() => (
                            <Popover>
                                <Popover.Trigger
                                    aria-label={labels.breakdownTitle}
                                    className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"

                                >
                                    {chip}
                                </Popover.Trigger>
                                <Popover.Content
                                    className="max-w-xs"

                                >
                                    {breakdownContent}
                                </Popover.Content>
                            </Popover>
                        )]
                        : []),
            ]}
        />
    )

    const savingLine = showSavingLine && (isSkeleton || hasSaving) ? (
        <Typography
            size="xs"
            color="muted"
            isSkeleton={isSkeleton}
            text={hasSaving ? `Save ${formatPrice(original - discounted, currency)}` : undefined}
        />
    ) : null

    return (
        // The outer column = two DIFFERENT lines (the price row ┬╖ the "saving" line) =>
        // `StackV`, NOT `Cluster`: a cluster is ONE track of N PEER elements (┬º13b).
        // `card-caption`: the saving line is a caption under the amount row ΓÇö same seam
        // TrialConversionStrip uses for price + scarcity.
        <StackV
            identity={identity}
            principle="card-caption"
            explain="Keeps the save line as a caption under the amount row so price + save read as one cluster."
            isSkeleton={isSkeleton}
            items={[
                () => priceRow,
                () => savingLine,
            ]}
        />
    )
}

"use client"

import React, {
    useCallback,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { formatVnd } from "@/modules/utils/format-vnd"
import { formatUsd } from "@/modules/utils/format-usd"
import type { AiSubscriptionTier } from "@/modules/api/graphql/queries/types/ai-subscription-tiers"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"
import { Button } from "@/components/atoms/buttons/Button"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH, StackV } from "@/components/frames/Stack"
import { TierLevelIcon } from "@/components/svg/TierLevelIcon"
import { TierCardBase } from "@/components/blocks/commerce/TierCardBase"

/** Props for {@link TierCard} (list item ΓÇö per-item tier data only). */
export interface TierCardProps {
    /** Tier this card represents. */
    /** The tier this card sells. Absent only while {@link TierCardProps.isSkeleton}. */
    tier?: AiSubscriptionTier
    /** Whether this tier is the user's current plan. */
    isCurrent: boolean
    /** First load ΓåÆ the shell rests; the twin that used to mirror this card is gone. */
    isSkeleton?: boolean
}

/** Placeholder for the resting card's slots ΓÇö the shell shimmers over every one of them. */
const EmptySlot = () => null

/**
 * One purchasable AI subscription tier card.
 *
 * List item: receives its own tier data + current flag; self-opens the shared
 * payment overlay for the buy action via {@link usePaymentOverlayState}.
 * Composes {@link TierCardBase} for the shared shell (surface color, no
 * shadow per global, `rounded-3xl`); the popular tier gets an accent border + ring.
 * @param props - tier, current state
 */
export const TierCard = ({
    tier,
    isCurrent,
    isSkeleton = false}: TierCardProps) => {
    const t = useTranslations()
    const { open: openPaymentModal } = usePaymentOverlayState()

    const onPress = useCallback(
        () => {
            if (!tier) {
                return
            }
            openPaymentModal({
                flow: PaymentFlow.AiSubscription,
                tier: tier.tier,
            })
        },
        [
            tier,
            openPaymentModal,
        ],
    )
    // Resting: the SHELL draws every box, so nothing here needs a tier yet. Returning
    // early is what lets the loaded branch below read `tier` without a guard on each line.
    if (isSkeleton || !tier) {
        return (
            <TierCardBase
                identity={{ tier: "block", component: "TierCard" }}
                isSkeleton
                icon={EmptySlot}
                title=""
                price={EmptySlot}
                features={[]}
                isCurrent={false}
                cta={EmptySlot}
            />
        )
    }

    // ascending tier level ΓÇö Plus=2, Pro=3, Max=4 (highlighted bars)
    const tierLevel = tier.tier === "max"
        ? 4
        : tier.tier === "pro"
            ? 3
            : 2
    return (
        <TierCardBase
            identity={{ tier: "block", component: "TierCard" }}
            className={tier.popular ? "border-accent ring-2 ring-accent/30" : undefined}
            icon={() => (
                <TierLevelIcon
                    level={tierLevel}
                    className="size-6 shrink-0 text-accent-soft-foreground"
                />
            )}
            title={tier.displayName}
            badge={tier.popular
                ? () => (
                    <Chip
                        tone="accent"
                        text={t("aiSubscription.popular")}
                    />
                )
                : undefined}
            description={tier.description ?? ""}
            price={() => (
                <StackV
                    principle="card-caption"
                    explain="Keeps the USD hint as a caption under the VND amount so price + period read as one cluster."
                    items={[
                        () => (
                            <StackH
                                principle="value-row"
                                explain="Holds the VND amount and /month period on one baseline so the period stays readable against the price."
                                items={[
                                    () => (
                                        <Typography size="h3" weight="bold" text={formatVnd(tier.priceVnd)} />
                                    ),
                                    () => (
                                        <Typography size="sm" color="muted" text={t("aiSubscription.perMonth")} />
                                    ),
                                ]}
                            />
                        ),
                        // Fixed 3lh slot so free/paid CTAs stay aligned across the grid.
                        () => (
                            <div className="h-[3lh]">
                                <Typography
                                    size="sm"
                                    color="muted"
                                    text={t("aiSubscription.priceUsdHint", { amount: formatUsd(tier.priceUsd) })}
                                />
                            </div>
                        ),
                    ]}
                />
            )}
            features={[
                t("aiSubscription.creditsPer5h", { credits: tier.creditsPer5h }),
                t("aiSubscription.creditsPerWeek", { credits: tier.creditsPerWeek }),
            ]}
            isCurrent={isCurrent}
            cta={() => (
                <StackV
                    principle="center-measure"
                    explain="Stretches the buy CTA across the card foot so it aligns with the free-tier disabled button."
                    items={[
                        () => (
                            <Button
                                variant="primary"
                                onPress={onPress}
                                label={t("aiSubscription.buy")}
                            />
                        ),
                    ]}
                />
            )}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Link, cn } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { EntityLink } from "@/components/blocks/feed/EntityLink"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { ReactionBar } from "./ReactionBar"
import { CommentComposer } from "./CommentComposer"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
/** Callbacks shared down the comment tree. */
export interface CommentItemCallbacks {
    /** Post a reply under `parentId`. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of `parentId`. */
    onLoadReplies: (parentId: string) => void
}

/** Props for {@link CommentItem}. */
export interface CommentItemProps extends CommentItemCallbacks {
    /** The comment to render. */
    comment: CommentNode
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Nesting depth (controls visual indentation). */
    depth: number
    /** Replies keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
}

/**
 * A single threaded comment with author, reactions, owner actions, reply box, and its
 * recursively-rendered replies. Visual indentation is capped so deep threads stay readable.
 *
 * Presentational: owns only transient UI state (editing/replying/expanded); persistence is
 * delegated via the {@link CommentItemCallbacks}.
 * @param props - {@link CommentItemProps}
 */
export const CommentItem = ({
    comment,
    currentUserId,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: CommentItemProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // transient per-comment UI state
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div
            className={cn("flex flex-col gap-2",
                // indent nested replies with a guide border, capped after a few levels
                depth > 0 ? "border-l border-default pl-3 @app-sm:pl-4" : undefined)}
        >
            <div className="flex gap-3">
                <UserAvatar
                    size="sm"
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                    className="mt-0 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                    {/* author + founder badge + timestamp header */}
                    <div className="flex flex-wrap items-center gap-2">
                        <EntityLink
                            label={comment.author.username}
                            onPress={() => router.push(
                                pathConfig().locale(locale).profile(comment.author.username).build(),
                            )}
                        />
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                aria-label={t("discussion.founderBadge")}
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <span className="text-xs text-muted">
                            {getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}
                        </span>
                        {comment.editedAt ? (
                            <span className="text-xs text-muted">{t("discussion.edited")}</span>
                        ) : null}
                    </div>

                    {/* body, edit form, or deleted placeholder */}
                    {comment.isDeleted ? (
                        <div className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</div>
                    ) : editing ? (
                        <CommentComposer
                            initialValue={comment.body}
                            submitLabel={t("common.save")}
                            onCancel={() => setEditing(false)}
                            onSubmit={(body) => {
                                onEdit(comment.id, body)
                                setEditing(false)
                            }}
                        />
                    ) : (
                        <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                            {comment.body}
                        </div>
                    )}

                    {/* action row: reactions + reply + owner edit/delete */}
                    {!comment.isDeleted && !editing ? (
                        <div className="flex flex-wrap items-center gap-3">
                            <ReactionBar
                                summary={comment.reactions}
                                onReact={(type) => onReactComment(comment.id, type)}
                            />
                            <Link
                                className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                onPress={() => setReplying((prev) => !prev)}
                            >
                                {t("discussion.reply")}
                            </Link>
                            {isOwner ? (
                                <>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                        onPress={() => setEditing(true)}
                                    >
                                        {t("common.edit")}
                                    </Link>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                        onPress={() => onDelete(comment.id)}
                                    >
                                        {t("common.delete")}
                                    </Link>
                                </>
                            ) : null}
                        </div>
                    ) : null}

                    {/* reply composer */}
                    {replying ? (
                        <CommentComposer
                            placeholder={t("discussion.replyPlaceholder")}
                            submitLabel={t("discussion.reply")}
                            onCancel={() => setReplying(false)}
                            onSubmit={(body) => {
                                onReply(comment.id, body)
                                setReplying(false)
                                // surface the new reply immediately by expanding the subtree
                                setExpanded(true)
                                onLoadReplies(comment.id)
                            }}
                        />
                    ) : null}

                    {/* replies toggle + recursive subtree */}
                    {comment.replyCount > 0 ? (
                        <Link
                            className="cursor-pointer self-start text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                            onPress={toggleReplies}
                        >
                            {expanded
                                ? t("discussion.hideReplies")
                                : t("discussion.viewReplies", { count: comment.replyCount })}
                        </Link>
                    ) : null}

                    {expanded && replies.length > 0 ? (
                        <div className="mt-1 flex flex-col gap-3">
                            {replies.map((reply) => (
                                <CommentItem
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    depth={depth + 1}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

import React from "react"
import {
    SearchAutocomplete,
    type SearchAutocompleteItem,
} from "@/components/atoms/forms/SearchAutocomplete"

/**
 * `ConsultantDirectoryCompanySearch` ΓÇö a typed, debounced deep-link to one
 * recruiting company's page, sitting above the consultant grid on the directory
 * screen. It is not a grid filter: there is no server-side search over
 * consultants, only a company suggester, so it jumps straight to a known
 * company page. `isLoadingSuggestions` swaps the popover's content.
 */

/** One company the ES suggester matched against the typed query. */
export interface ConsultantCompanySuggestion {
    /** Stable company id ΓÇö the payload handed back through `onSelectCompany`. */
    id: string
    /** Company display name, already localized/formatted by the caller. */
    label: string
}

/** Props for {@link ConsultantDirectoryCompanySearch}. */
export interface ConsultantDirectoryCompanySearchProps {
    /** Current text in the search field (controlled). */
    query: string
    /** Fired with the new query on every keystroke; the screen owns debouncing. */
    onQueryChange: (value: string) => void
    /** Company matches for the current query, already fetched by the screen. */
    suggestions: Array<ConsultantCompanySuggestion>
    /** `true` while the screen is waiting on the ES company-suggester. */
    isLoadingSuggestions?: boolean
    /** Fired with the picked company's id; the screen owns the route push. */
    onSelectCompany: (companyId: string) => void
}

/**
 * The company deep-link search row atop the consultant directory. See the file
 * header for why this is a jump-to-company control and not a grid filter.
 *
 * @param props - {@link ConsultantDirectoryCompanySearchProps}
 */
const ConsultantDirectoryCompanySearch = ({
    query,
    onQueryChange,
    suggestions,
    isLoadingSuggestions = false,
    onSelectCompany,
}: ConsultantDirectoryCompanySearchProps) => {
    const items: Array<SearchAutocompleteItem> = suggestions.map((company) => ({
        id: company.id,
        label: company.label,
    }))

    // Sole root is SearchAutocomplete ΓÇö inert host wrappers removed. Identity
    // stays held until the atom accepts CallerIdentity (CourseTrialChip pattern).
    return (
        <SearchAutocomplete
            items={items}
            inputValue={query}
            onInputChange={onQueryChange}
            onSelect={onSelectCompany}
            isLoading={isLoadingSuggestions}
            // Owned wording: this field jumps to ONE company, it does not filter
            // the grid below it ΓÇö the placeholder has to say so or a visitor will
            // type a role/skill and get nothing back.
            placeholder="Search for a hiring company by nameΓÇª"
            emptyLabel="No companies found"
        />
    )
}

export { ConsultantDirectoryCompanySearch }

import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@/components/composites/async/AsyncContent"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"
import { Typography } from "@/components/atoms/text/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@/components/blocks/consultant/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` ΓÇö the consultant directory's browse surface: a
 * match count above the cards, across the loading ΓåÆ empty ΓåÆ content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ΓçÆ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ΓçÆ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` ΓÇö this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region ΓÇö the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved ΓÇö ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` ΓÇö `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (┬º14d.1) ΓÇö the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton
            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}
            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,
    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={skeletonTiles}  />
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}
                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={tiles}  />
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

"use client"

import React from "react"
import { Button, Input, Label, TextField } from "@heroui/react"
import { useTranslations } from "next-intl"
import { PlusIcon } from "@phosphor-icons/react"
import type { CvBlock, CvBlockEditorProps, CvBlockItem } from "@/modules/types/entities/cv"
import { StackV } from "@/components/frames/Stack"
import { RepeatableItemCard } from "../shared/RepeatableItemCard"

/** A brand-new, empty achievement entry. */
const emptyItem = (): CvBlockItem => ({ id: crypto.randomUUID(), fields: {} })

/** Props for {@link AchievementBlockEditor}. */
export type AchievementBlockEditorProps = CvBlockEditorProps 

/**
 * Freeform achievements block editor (outside awards, certifications) ΓÇö
 * repeatable, self-reported, never scored. No AI affordance (per
 * `CV_BLOCK_TYPE_REGISTRY[Achievement]`).
 *
 * Shell is StackV with identity. HeroUI TextField/Input/Button remain ΓÇö
 * house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
 *
 * @param props - {@link AchievementBlockEditorProps}
 */
export const AchievementBlockEditor = ({ block, onChange }: AchievementBlockEditorProps) => {
    const t = useTranslations()

    const setItems = (items: Array<CvBlockItem>) => onChange({ ...block, items } satisfies CvBlock)

    const onFieldChange = (itemId: string, key: string, value: string) => {
        setItems(block.items.map((item) => (
            item.id === itemId ? { ...item, fields: { ...item.fields, [key]: value } } : item
        )))
    }

    const onAddItem = () => setItems([...block.items, emptyItem()])
    const onRemoveItem = (itemId: string) => setItems(block.items.filter((item) => item.id !== itemId))
    const onMove = (index: number, direction: -1 | 1) => {
        const next = [...block.items]
        const target = index + direction
        if (target < 0 || target >= next.length) {
            return
        }
        [next[index], next[target]] = [next[target], next[index]]
        setItems(next)
    }

    const itemCount = block.items.length

    return (
        <StackV
            identity={{ tier: "block", component: "AchievementBlockEditor" }}
            principle="sibling-stack"
            explain="Same-kind peer stack of repeatable achievement cards ΓÇö not group-boundary, because each card is a repeating peer rather than a section group."
            items={[
                ...block.items.map((item, index) => () => (
                    <RepeatableItemCard
                        onRemove={() => onRemoveItem(item.id)}
                        onMoveUp={index > 0 ? () => onMove(index, -1) : undefined}
                        onMoveDown={index < itemCount - 1 ? () => onMove(index, 1) : undefined}
                    >
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-title-${item.id}`}>
                                {t("cv.blocks.achievement.fields.title")}
                            </Label>
                            <Input
                                id={`cv-achievement-title-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.title")}
                                value={typeof item.fields.title === "string" ? item.fields.title : ""}
                                onChange={(event) => onFieldChange(item.id, "title", event.target.value)}
                            />
                        </TextField>
                        <TextField variant="secondary">
                            <Label htmlFor={`cv-achievement-description-${item.id}`}>
                                {t("cv.blocks.achievement.fields.description")}
                            </Label>
                            <Input
                                id={`cv-achievement-description-${item.id}`}
                                placeholder={t("cv.blocks.achievement.placeholders.description")}
                                value={typeof item.fields.description === "string" ? item.fields.description : ""}
                                onChange={(event) => onFieldChange(item.id, "description", event.target.value)}
                            />
                        </TextField>
                    </RepeatableItemCard>
                )),
                () => (
                    <Button variant="tertiary" size="sm" className="w-fit self-start" onPress={onAddItem}>
                        <PlusIcon aria-hidden className="size-4" />
                        {t("cv.blocks.achievement.addItem")}
                    </Button>
                ),
            ]}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Calendar, DateField, DatePicker, FieldError, Input, Label, TextField } from "@heroui/react"
import { getLocalTimeZone, parseDate, today } from "@internationalized/date"
import type { DateValue } from "@internationalized/date"
import { useTranslations } from "next-intl"
import type { CvBlockEditorProps } from "@/modules/types/entities/cv"
import { isValidOptionalUrl } from "@/modules/utils/cv-url"
import { Grid, type GridItem } from "@/components/frames/Grid"

/** Field keys read/written on the single `personal` item's `fields`. */
const FIELD_KEYS = [
    "name",
    "role",
    "email",
    "phone",
    "location",
    "birthDate",
    "linkedinUrl",
    "githubUsername",
] as const
type PersonalFieldKey = typeof FIELD_KEYS[number]

/** The only field key validated as a URL (blur-triggered, per `isValidOptionalUrl`). */
const URL_FIELD_KEYS: ReadonlySet<PersonalFieldKey> = new Set(["linkedinUrl"])

/** Parses a stored ISO date string (e.g. `"2000-01-01"`) into a `DateValue`, or `null` if empty/unparseable. */
const parseStoredDate = (value: string): DateValue | null => {
    if (!value) {
        return null
    }
    try {
        return parseDate(value)
    } catch {
        return null
    }
}

/** Props for {@link PersonalBlockEditor}. */
export type PersonalBlockEditorProps = CvBlockEditorProps 

/**
 * Header/contact block editor ΓÇö singleton, non-repeatable, no AI affordance
 * (per `CV_BLOCK_TYPE_REGISTRY[Personal]`). Holds its one fields set on
 * `block.items[0]` (created on first edit if the block starts with 0 items,
 * per the uniform `CvBlock` shape every block type shares).
 *
 * @param props - {@link PersonalBlockEditorProps}
 */
export const PersonalBlockEditor = ({ block, onChange }: PersonalBlockEditorProps) => {
    const t = useTranslations()
    const fields = block.items[0]?.fields ?? {}
    const [touchedUrlKeys, setTouchedUrlKeys] = useState<ReadonlySet<PersonalFieldKey>>(new Set())

    const onFieldChange = (key: PersonalFieldKey, value: string) => {
        const item = block.items[0] ?? { id: crypto.randomUUID(), fields: {} }
        const nextItem = { ...item, fields: { ...item.fields, [key]: value } }
        onChange({ ...block, items: [nextItem] })
    }

    const onBlurUrlField = (key: PersonalFieldKey) => {
        setTouchedUrlKeys((prev) => new Set(prev).add(key))
    }

    // Shell is Grid with identity. HeroUI DatePicker/TextField remain ΓÇö
    // house form migration is contract `CvBlockEditorFormSurface` (vendor boundary).
    const items: Array<GridItem> = FIELD_KEYS.map((key) => {
        const value = typeof fields[key] === "string" ? (fields[key] as string) : ""

        if (key === "birthDate") {
            return {
                key,
                content: () => (
                    <DatePicker
                        aria-label={t("cv.blocks.personal.fields.birthDate")}
                        maxValue={today(getLocalTimeZone())}
                        value={parseStoredDate(value)}
                        onChange={(date) => onFieldChange(key, date ? date.toString() : "")}
                    >
                        <Label>{t("cv.blocks.personal.fields.birthDate")}</Label>
                        <DateField.Group fullWidth variant="secondary">
                            <DateField.Input>
                                {(segment) => <DateField.Segment segment={segment} />}
                            </DateField.Input>
                            <DateField.Suffix>
                                <DatePicker.Trigger>
                                    <DatePicker.TriggerIndicator />
                                </DatePicker.Trigger>
                            </DateField.Suffix>
                        </DateField.Group>
                        <DatePicker.Popover>
                            <Calendar aria-label={t("cv.blocks.personal.fields.birthDate")}>
                                <Calendar.Header>
                                    <Calendar.YearPickerTrigger>
                                        <Calendar.YearPickerTriggerHeading />
                                        <Calendar.YearPickerTriggerIndicator />
                                    </Calendar.YearPickerTrigger>
                                    <Calendar.NavButton slot="previous" />
                                    <Calendar.NavButton slot="next" />
                                </Calendar.Header>
                                <Calendar.Grid>
                                    <Calendar.GridHeader>
                                        {(day) => <Calendar.HeaderCell>{day}</Calendar.HeaderCell>}
                                    </Calendar.GridHeader>
                                    <Calendar.GridBody>
                                        {(date) => <Calendar.Cell date={date} />}
                                    </Calendar.GridBody>
                                </Calendar.Grid>
                                <Calendar.YearPickerGrid>
                                    <Calendar.YearPickerGridBody>
                                        {({ year }) => <Calendar.YearPickerCell year={year} />}
                                    </Calendar.YearPickerGridBody>
                                </Calendar.YearPickerGrid>
                            </Calendar>
                        </DatePicker.Popover>
                    </DatePicker>
                ),
            }
        }

        const isUrlField = URL_FIELD_KEYS.has(key)
        const isInvalid = isUrlField && touchedUrlKeys.has(key) && !isValidOptionalUrl(value)
        return {
            key,
            content: () => (
                <TextField variant="secondary" isInvalid={isInvalid}>
                    <Label htmlFor={`cv-personal-${key}`}>
                        {t(`cv.blocks.personal.fields.${key}`)}
                    </Label>
                    <Input
                        id={`cv-personal-${key}`}
                        placeholder={t(`cv.blocks.personal.placeholders.${key}`)}
                        value={value}
                        onChange={(event) => onFieldChange(key, event.target.value)}
                        onBlur={isUrlField ? () => onBlurUrlField(key) : undefined}
                    />
                    {isUrlField ? (
                        <FieldError>{t("cv.blocks.common.invalidUrl")}</FieldError>
                    ) : null}
                </TextField>
            ),
        }
    })

    return (
        <Grid
            identity={{ tier: "block", component: "PersonalBlockEditor" }}
